INSERT INTO public.projects (id, title, description, long_description, technologies, github_url, live_url, paper_url, image_url, featured, category, start_date, end_date, status, impact, metrics, sort_order, created_at, updated_at) VALUES
('esp32-gesture-robot-car', 'ESP32 Gesture-Controlled Robot Car', 'A handheld gyroscope remote wirelessly driving a 4WD robot car over ESP-NOW.', 'This project pairs a handheld remote with a separate car unit, both built on ESP32s. The remote reads tilt data from an MPU6050 gyroscope and streams it wirelessly over ESP-NOW to the car unit, which translates that tilt into motor commands. The car itself is a 4WD build — four TT gear motors wired in left/right pairs on a plywood strip chassis — powered by two 18650 Li-ion cells with onboard USB charging and a slide power switch. It runs on ESP-IDF and FreeRTOS rather than the Arduino framework, keeping gesture-sensing and the wireless link running as proper concurrent tasks.', '{"ESP32","ESP-IDF","FreeRTOS","ESP-NOW","MPU6050","Motor Control"}', NULL, NULL, NULL, NULL, false, 'embedded', '2026', '2026', 'completed', 'Controlling a robot with a tilt of the wrist.', '{"Handheld MPU6050 gyroscope remote","Wireless ESP-NOW link between remote and car unit","4WD chassis with independent left/right motor control","Li-ion powered with onboard USB charging"}', 0, now(), now())
ON CONFLICT (id) DO NOTHING;

-- confidence: medium — sourced from informal working notes, not the resume; framed as a learning exercise, verify current status before treating as final
INSERT INTO public.projects (id, title, description, long_description, technologies, github_url, live_url, paper_url, image_url, featured, category, start_date, end_date, status, impact, metrics, sort_order, created_at, updated_at) VALUES
('async-job-board', 'Async Job Board', 'A full-stack job board built by hand to go deep on Go and TypeScript fundamentals — a worker-pool backend and a class-based frontend with no frameworks.', 'I built this job board application from scratch as a deliberate learning exercise, writing every line by hand in Neovim rather than scaffolding it with a framework. The backend is Go, built around a worker pool for handling background jobs and talking to PostgreSQL through pgx. The frontend is TypeScript structured around plain object-oriented class patterns — an ApiClient for network calls, a JobStore for state, a JobPoller for real-time updates, and abstract View subclasses for rendering — instead of reaching for React or another framework.', '{"Go","PostgreSQL","pgx","TypeScript","OOP Frontend Architecture"}', NULL, NULL, NULL, NULL, false, 'web', '2026', NULL, 'ongoing', 'Going deep on Go and TypeScript by building everything by hand.', '{"Go backend built around a worker pool","PostgreSQL access via pgx, no ORM","Hand-written TypeScript frontend with OOP class architecture","No frameworks — every line written from scratch in Neovim"}', 0, now(), now())
ON CONFLICT (id) DO NOTHING;

